function setAviso(txt, tipo){
  const el = $$('avisoValor');
  if (avisoTimer){ clearTimeout(avisoTimer); avisoTimer = null; }
  el.className = 'aviso' + (tipo === 'ok' ? ' is-ok' : (tipo === 'err' ? ' is-err' : ''));
  el.textContent = txt || '';
  if (tipo === null){
    el.style.display = 'none';
    return;
  }
  el.style.display = 'block';
  el.classList.remove('entra', 'removendo');
  void el.offsetWidth; // forçar reflow
  el.classList.add('entra');
  avisoTimer = setTimeout(() => {
    el.classList.remove('entra');
    el.classList.add('removendo');
    el.style.transition = 'none';
    setTimeout(() => { el.style.display = 'none'; }, 220);
    avisoTimer = null;
  }, 360);
}
function limparAviso(){
  const el = $$('avisoValor');
  el.className = '';
  el.textContent = '';
  el.style.display = 'none';
}
function setErro(idElem, texto, manter){
  const el = $$(idElem);
  el.textContent = texto;
  el.classList.toggle('ativa', Boolean(texto) && !manter);
}
function aplicarEspacos(valores){
  if (valores.length <= 4) return valores;
  const g1 = valores.slice(0, 4);
  return (valores.length > 4 ? ' ' : '') + g1 + valores.slice(4);
}

